 const requested=new Set(additional),multiStage=new Set(multi),needed=new Set(),ownerCounts=new Map();for(const id of requested){const owners=available.filter(stage=>stage.testIds.includes(id));assert(owners.length>=1,'Reviewed test requires one existing stage or declared multi-stage owners: '+id);assert.equal(multiStage.has(id),owners.length>1,'Reviewed multi-stage ownership drift: '+id);ownerCounts.set(id,owners.length);for(const owner of owners)needed.add(owner.id);}for(const id of multiStage)assert(requested.has(id),'Reviewed multi-stage test is not selected: '+id);const present=new Set(scenarios.map(stage=>stage.produces));for(let changed=true;changed;){changed=false;for(const stage of available.filter(row=>needed.has(row.id)))for(const requirement of stage.requires??[])if(!present.has(requirement)){const producers=available.filter(row=>row.produces===requirement);assert.equal(producers.length,1,'Reviewed dependency requires one existing stage: '+requirement);if(!needed.has(producers[0].id)){needed.add(producers[0].id);changed=true;}}}
