 const selected=scenarios.flatMap(stage=>stage.testIds),counts=selected.reduce((values,id)=>values.set(id,(values.get(id)??0)+1),new Map());assert.deepEqual(new Set(selected),new Set([...base,...additional]),'Reviewed union drift');for(const id of additional)assert.equal(counts.get(id),ownerCounts.get(id),'Reviewed test owner count drift: '+id);for(const id of base)assert.equal(counts.get(id),1,'Reviewed base test repeated: '+id);const produced=new Set();for(const stage of scenarios){for(const requirement of stage.requires??[])assert(produced.has(requirement),'Reviewed stage dependency missing: '+requirement);produced.add(stage.produces);}
